{"rob": "robolang 1.3;

task bring_boxes(robot r, object first, object second, location pick_a, location pick_b, location dst) {
    goal { object_at first dst; object_at second dst; }
    plan {
        move r to pick_a;
        grasp r first;
        move r to dst;
        place r first at dst;
        move r to pick_b;
        grasp r second;
        move r to dst;
        place r second at dst;
    }
}
", "task": "bring_boxes", "bindings": [{"param": "r", "id": "arm1"}, {"param": "first", "id": "box1"}, {"param": "second", "id": "box2"}, {"param": "pick_a", "id": "shelf_a"}, {"param": "pick_b", "id": "shelf_b"}, {"param": "dst", "id": "table"}]}
